#include <bits/stdc++.h>
using namespace std;

long long solve() {
    int n, k;
    cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    vector<int> b(n);
    for (int i = 0; i < n; ++i) {
        cin >> b[i];
    }
    vector<long long> res;
    for (int i = 0; i < n; ++i) {
        if (b[i] == 0) continue;
        long long x = min(k, 1e18);
        k -= x;
        a[i] += x;
        vector<long long> s(a.begin(), a.end());
        sort(s.begin(), s.end());
        s.erase(s.begin() + i);
        long long median = s[(n-1)/2];
        res.push_back(a[i] + median);
    }
    return *max_element(res.begin(), res.end());
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        cout << solve() << '\n';
    }
    return 0;
}
